create or replace TABLE SZD_PRODUCTION.CORE_REL.T_CONSIGNOR_ORDER_LIST_1 (
	TRADER_REFERENCE_NR VARCHAR(250) NOT NULL COMMENT 'Natural Key/Business Key - This is a reference assigned by the declarant for the goods covered by the declaration.',
	ORDER_DT DATE NOT NULL COMMENT 'Natural Key/Business Key - The date when the goods were ordered by the consignor.',
	AUTHORITY_COUNTRY_LOCATION_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the country_1 of the customs authority.',
	CONSIGNOR_PARTY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the consignor.',
	ORIGINAL_CONSIGNOR_PARTY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the original consignor.',
	CARRIER_PARTY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the carrier company.',
	CONSIGNEE_PARTY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the consignee party.',
	EXPORT_WAREHOUSE_RESOURCE_ITEM_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the export warehouse (only WWT).',
	DEPARTURE_COUNTRY_LOCATION_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the departure country_1 (only BEI).',
	CUSTOMS_OFFICE_PARTY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the customs office.',
	INVOICE_FINANCE_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the invoice (only WWT).',
	TRANSPORT_TYPE_CD VARCHAR(50) NOT NULL COMMENT 'The unique identifier of the transport mode (only BEI).',
	TRANSPORT_ROUTE_TYPE_CD VARCHAR(50) NOT NULL COMMENT 'The unique code of the transport route type(only BEI).',
	TRANSPORT_REFERENCE_NR VARCHAR(250) COMMENT 'Descriptive attribute - The transport reference is used to track the transport to the destination (only BEI).',
	DISPO_WEEK NUMBER(38,0) COMMENT 'Descriptive Attribute - The dispo week (only WWT).',
	ROLL_ON_ROLL_OFF_FG BOOLEAN COMMENT 'Flag indicating whether if this \"Roll on Roll off\" (only BEI)..',
	PURCHASE_ORDER_NR VARCHAR(250) COMMENT 'Descriptive attribute - The order number of a truck load (only BEI).',
	SHIPMENT_NR VARCHAR(250) COMMENT 'Descriptive attribute - The shipment number (only provided by OWIM in BEI)',
	PORT_OF_ARRIVAL_TXT VARCHAR(1000) COMMENT 'Descriptive attribute - The port where the goods will arrive (only BEI).',
	ESTIMATED_ARRIVAL_DT DATE COMMENT 'Descriptive attribute - The date of the estimated departure of the goods (only BEI).',
	ESTIMATED_DEPARTURE_DT DATE COMMENT 'Descriptive attribute - The date of the estimated arrival of the goods at the destination (only BEI).',
	BILL_OF_LEDING_NR VARCHAR(250) COMMENT 'Descriptive Attribute - The number of the bill of lading (only BEI).',
	PACKAGING_LIST_NR VARCHAR(250) COMMENT 'Descriptive Attribute - The reference number of the packing list (only BEI).',
	CONTAINER_NR_TXT VARCHAR(1000) COMMENT 'Descriptive Attribute - The container number(s) where the goods are transported in (only BEI).',
	VESSEL_COUNTRY_LOCATION_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the nationality of the vessel (only BEI)',
	VESSEL_NAME VARCHAR(100) COMMENT 'Descriptive Attribute - The identifier/name of the vessel (only BEI)',
	FERRY_COUNTRY_LOCATION_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the nationality of the ferry (only BEI).',
	FERRY_NAME VARCHAR(100) COMMENT 'Descriptive Attribute - The identifier/name of the ferry (only BEI)',
	TRUCK_COUNTRY_LOCATION_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the nationality of the truck (only BEI).',
	TRUCK_NAME VARCHAR(100) COMMENT 'Descriptive Attribute - The identifier/name of the truck (only BEI)',
	TRAILER_COUNTRY_LOCATION_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the nationality of the trailer (only BEI).',
	TRAILER_NAME VARCHAR(100) COMMENT 'Descriptive Attribute - The identifier/name of the trailer (only BEI)',
	TRAIN_COUNTRY_LOCATION_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the nationality of the train (only BEI).',
	TRAIN_NAME VARCHAR(100) COMMENT 'Descriptive Attribute - The identifier/name of the train (only BEI)',
	LOADING_REFERENCE_NR VARCHAR(250) COMMENT 'Descriptive Attribute - The loading reference number  (usually a combination of packaging list number and container number) (only BEI).',
	INBOUND_DELIVERY_NR VARCHAR(250) COMMENT 'Descriptive Attribute - The inbound delivery number identifies the way materials and other goods are brought into a company. (only BEI)',
	INBOUND_DELIVERY_DT DATE COMMENT 'Descriptive Attribute - The time that inbound delievry is created. (only BEI)',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created or last updated.',
	DWH_SRC_FILE_NAME VARCHAR(500) NOT NULL COMMENT 'Contains the name(s) of the input file(s) that delivered the record. It can be either the full path of the BLOG storage or the shortened file path',
	DWH_SRC_1_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The extraction timestamp of the record from the source',
	constraint PK_CONSIGNOR_ORDER_LIST primary key (TRADER_REFERENCE_NR, ORDER_DT)
)COMMENT='Entity - Transactional - Transaction - The consignor order list contains a list of orders for goods to be imported for specific consignees. This list serves as a basis for the broker to create the customs declaration and the broker''s report. This order list contains all the information that the broker needs to calculate the expected duties. There are two sources (BEI and WWT) for this report which provide different data. The data structures do not follow any standard. Therefore it is necessary to model two separate entities for BEI and WWT respectively. - Source - BEI/WWT Report'
;